function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateObj(s){const d=new Date(s+'T12:00:00');d.setHours(0,0,0,0);return d}
function daysAgo(n){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function loadState(){try{const current=localStorage.getItem(STORAGE);if(current)return JSON.parse(current);const legacy=localStorage.getItem('gym-training-os-v3')||localStorage.getItem('gym-training-os-v2');return legacy?JSON.parse(legacy):{}}catch{return {}}}
function saveState(s){localStorage.setItem(STORAGE,JSON.stringify(s))}
function fmt(n){return n?Math.round(n*2)/2:0}
function lastFor(history,ex,day){return history.filter(x=>x.exercise===ex&&x.day===day).sort((a,b)=>b.date.localeCompare(a.date))[0]}
function suggestedLoad(ex,day,history,settings,adjust=1){const last=lastFor(history,ex,day);const base=settings.loads?.[ex]??defaultLoad[ex]??0;if(!last)return fmt(base*adjust);const stalled=(last.stalled||0);if(stalled>=2)return fmt(last.weight*.9*adjust);if(last.hitTop&&last.rir>=1)return fmt(last.weight*(ex.toLowerCase().includes('dumbbell')||/curl|raise|extension|pushdown/i.test(ex)?1.025:1.05)*adjust);return fmt(last.weight*adjust)}
function calcBBLoad(x){return Math.min(100,Math.round((x.duration*(x.factor||1))+(x.jumps||0)*.7+(x.intensity-3)*7))}
function calcRunLoad(x){return Math.min(100,Math.round((Number(x.distance)||0)*8+(Number(x.duration)||0)*.25+(Number(x.intensity||3)-3)*8))}
function basketballMetrics(bbLogs,history,soreness,runLogs=[]){
 const now=dateObj(today()),logs=bbLogs||[],runs=runLogs||[];
 const age=x=>(now-dateObj(x.date))/86400000;
 const bb7=logs.filter(x=>age(x)<7),run7=runs.filter(x=>age(x)<7);
 const acuteBB=bb7.reduce((a,x)=>a+Number(x.load||0),0), acuteRun=run7.reduce((a,x)=>a+Number(x.load||0),0);
 const acute=acuteBB+acuteRun*.65;
 const prior28=logs.filter(x=>age(x)>=7&&age(x)<35).reduce((a,x)=>a+Number(x.load||0),0)+runs.filter(x=>age(x)>=7&&age(x)<35).reduce((a,x)=>a+Number(x.load||0)*.65,0);
 const chronic=prior28/4;
 const ratio=chronic>0?acute/chronic:0;
 const recentJumps=bb7.reduce((a,x)=>a+Number(x.jumps||0),0);
 const last48=logs.filter(x=>age(x)<2).reduce((a,x)=>a+Number(x.load||0),0)+runs.filter(x=>age(x)<2).reduce((a,x)=>a+Number(x.load||0)*.65,0);
 const recentLeg=history.filter(x=>(x.day==='Legs'||x.day==='Full Body')&&age(x)<4).length;
 const hasExternalLoad=acute>0;
 let score=100;
 if(hasExternalLoad){score-=Math.min(45,acute*.45);score-=Math.min(15,recentJumps*.25);score-=Math.min(18,last48*.18);if(ratio>1.5)score-=8;if((soreness||2)>2)score-=(soreness-2)*7;}
 else if((soreness||2)>2) score-=(soreness-2)*5;
 score=Math.max(0,Math.min(100,Math.round(score)));
 const status=score>=75?'READY':score>=50?'MODERATE':'PROTECT';
 const adjustment=score>=75?1:score>=50?.9:.8;
 return {acuteBB:Math.round(acuteBB),acuteRun:Math.round(acuteRun),acute:Math.round(acute),chronic:Math.round(chronic),ratio:Number(ratio.toFixed(2)),recentJumps,last48:Math.round(last48),recentLeg,score,status,adjustment,hasExternalLoad};
}
function adjustedPlan(day,recovery){
 const base=PROGRAM[day].exercises;
 if((day!=='Legs'&&day!=='Full Body')||(!recovery.hasExternalLoad&&recovery.score>=50)) return {exercises:base,adjusted:false,scale:1};
 if(recovery.status==='READY') return {exercises:base,adjusted:false,scale:1};
 const scale=recovery.adjustment;
 return {exercises:base.map((e,i)=>{let sets=Math.max(1,Math.ceil(e[1]*scale));if(recovery.status==='PROTECT'&&i===0)sets=Math.min(2,sets);return [...e.slice(0,1),sets,...e.slice(2)]}),adjusted:true,scale};
}

