function SessionTimer({session,elapsed,onStart,onPause,onResume,onFinish}){const total=Math.floor(elapsed/1000),h=Math.floor(total/3600),m=Math.floor((total%3600)/60),sec=total%60;return <section className="sessionTimer"><div><span className="eyebrow">SESSION TIMER</span><strong>{h?`${String(h).padStart(2,'0')}:`:''}{String(m).padStart(2,'0')}:{String(sec).padStart(2,'0')}</strong><small>{session?.running?'SESSION RUNNING':session?'PAUSED':'START WHEN YOU BEGIN'}</small></div><div className="timerBtns">{!session?<button className="play" onClick={onStart}><Play/> Start</button>:session.running?<button className="play" onClick={onPause}><Pause/> Pause</button>:<button className="play" onClick={onResume}><Play/> Resume</button>}{session&&<button onClick={onFinish}><Check/> Finish</button>}</div></section>}
function Timer({timer,setTimer,running,setRunning}){const presets=[60,90,120,180];return <section className="timerCard"><div><span className="eyebrow">REST TIMER</span><strong>{String(Math.floor(timer/60)).padStart(2,'0')}:{String(timer%60).padStart(2,'0')}</strong></div><div className="timerBtns">{presets.map(x=><button key={x} onClick={()=>{setTimer(x);setRunning(false)}}>{x>=60?`${x/60}m`:x+'s'}</button>)}<button className="play" onClick={()=>setRunning(!running)}>{running?<Pause/>:<Play/>}</button></div></section>}
function Exercise({ex,i,suggested,pb,log,save,onTimer,onSub,substitution}){const [expanded,setExpanded]=useState(i===0);const repsDefault=Array.from({length:ex[1]},()=>ex[3]);const setDone=(s)=>save({[`s${s}`]:!log[`s${s}`]});const best=Number(pb||0);return <article className={'exercise '+(log.done?'done':'')}><button className="exerciseTop" onClick={()=>setExpanded(!expanded)}><div className="num">{String(i+1).padStart(2,'0')}</div><div className="exTitle"><h3>{ex[0]} {log.superset&&<span className="supersetTag">SUPERSET</span>}</h3><p>{ex[1]} sets · {ex[2]}–{ex[3]} reps</p></div><div className="loadMini">{suggested||'BW'}<small>{suggested?'kg':''}</small></div><ChevronRight className={expanded?'rot':''}/></button>{expanded&&<div className="exerciseBody"><div className="recommend"><span><TrendingUp/> Next target</span><b>{suggested?`${suggested} kg`:'Bodyweight'} · {ex[2]}–{ex[3]} reps</b><small>{best>0?`Current PB: ${best} kg. `:''}Hit the top of the range on every set with RIR ≥1 to earn a load increase. Two stalls triggers a deload suggestion.</small></div>{substitution&&<div className="subNotice"><RefreshCw/> Using <b>{substitution}</b> instead of {ex[0]}</div>}{Array.from({length:ex[1]},(_,s)=><div className="setRow" key={s}><span>{s+1}</span><input value={log.weight??suggested} onChange={e=>save({weight:e.target.value})}/><b>kg</b><input value={log[`r${s}`]??repsDefault[s]} onChange={e=>save({[`r${s}`]:e.target.value})}/><b>reps</b><button className={log[`s${s}`]?'check on':'check'} onClick={()=>setDone(s)}><Check/></button></div>)}<div className="logBottom"><label>RIR <select value={log.rir??2} onChange={e=>save({rir:e.target.value})}><option>0</option><option>1</option><option>2</option><option>3</option></select></label><button onClick={onTimer}><Clock3/> Rest</button><button onClick={()=>save({superset:!log.superset})}>{log.superset?'Remove':'Add'} superset</button><button onClick={onSub}><RefreshCw/> Substitute</button><button className={log.done?'doneBtn':''} onClick={()=>save({done:!log.done})}>{log.done?<Check/>:'✓'} {log.done?'Logged':'Mark exercise'}</button></div></div>}</article>}

function WaterCard({state,setState}){const date=today();const intake=Number(state.waterLogs?.[date]||0),goal=Number(state.waterGoal||3000),pct=Math.min(100,Math.round(intake/goal*100));const add=(ml)=>setState(s=>({...s,waterLogs:{...(s.waterLogs||{}),[date]:Math.max(0,Number(s.waterLogs?.[date]||0)+ml)}}));return <section className="waterCard"><div className="sectionHead"><div><span className="eyebrow">HYDRATION</span><h2>Water today</h2></div><b>{(intake/1000).toFixed(2)} / {(goal/1000).toFixed(1)} L</b></div><div className="waterTrack"><i style={{width:`${pct}%`}}/></div><div className="waterActions"><button onClick={()=>add(250)}>+250 ml</button><button onClick={()=>add(500)}>+500 ml</button><button onClick={()=>add(750)}>+750 ml</button><button className="ghost" onClick={()=>setState(s=>({...s,waterLogs:{...(s.waterLogs||{}),[date]:0}}))}>Reset</button></div><p>{pct>=100?'Daily target reached.':`${goal-intake>0?Math.ceil((goal-intake)/250)*250:0} ml to go.`} Log water as you drink it; the app keeps it by date.</p></section>}

function Cardio({state,setState,recovery}){const [distance,setDistance]=useState(5),[duration,setDuration]=useState(30),[intensity,setIntensity]=useState(3);const [showLog,setShowLog]=useState(false);const load=calcRunLoad({distance,duration,intensity});const logs=state.runLogs||[];const logRun=()=>{setState(s=>({...s,runLogs:[...(s.runLogs||[]),{date:today(),distance:Number(distance),duration:Number(duration),intensity:Number(intensity),load}]}));setShowLog(false)};return <section><section className="hero simple"><div><div className="eyebrow">CARDIO OS</div><h1>Runs</h1><p>Log your runs by distance and keep cardio inside the same weekly training picture.</p></div><div className="heroStat"><span>{logs.filter(x=>x.date>=daysAgo(6)).reduce((a,x)=>a+Number(x.distance||0),0).toFixed(1)} km</span><small>7-day distance</small></div></section><SessionLogTimer type="run" state={state} setState={setState} label="RUN SESSION"/><div className="loadLogger"><div className="sectionHead"><div><span className="eyebrow">LOG A RUN</span><h2>Record today's cardio</h2></div><div className="loadPreview"><b>{load}</b><small>load</small></div></div><div className="loggerGrid"><label>Distance (km)<input type="number" min="0.1" step="0.1" value={distance} onChange={e=>setDistance(e.target.value)}/></label><label>Duration (min)<input type="number" min="1" value={duration} onChange={e=>setDuration(e.target.value)}/></label><label>Intensity (1–5)<select value={intensity} onChange={e=>setIntensity(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option key={x}>{x}</option>)}</select></label></div><p className="loggerHint">Running contributes to your weekly workload. Harder or longer runs also feed the recovery engine so leg training does not ignore your cardio.</p><button className="finish" onClick={()=>setShowLog(true)}>Log run <span>{Number(distance).toFixed(1)} km · {load} load</span></button></div><div className="rules"><h2>Weekly cardio</h2><div className="miniMetrics"><div><b>{logs.filter(x=>x.date>=daysAgo(6)).length}</b><span>runs</span></div><div><b>{logs.filter(x=>x.date>=daysAgo(6)).reduce((a,x)=>a+Number(x.distance||0),0).toFixed(1)}</b><span>km</span></div><div><b>{logs.filter(x=>x.date>=daysAgo(6)).reduce((a,x)=>a+(x.load||0),0)}</b><span>run load</span></div><div><b>{recovery.score}</b><span>readiness</span></div></div></div><div className="rules"><h2>Run history</h2>{logs.slice(-8).reverse().map((x,i)=><div className="bbHistory" key={i}><div><b>{x.distance} km run</b><span>{x.date} · {x.duration} min · intensity {x.intensity}/5</span><strong>{x.load}</strong></div></div>)}{!logs.length&&<p>No runs logged yet.</p>}</div>{showLog&&<div className="modal" onClick={()=>setShowLog(false)}><div className="modalBox" onClick={e=>e.stopPropagation()}><span className="eyebrow">CONFIRM RUN</span><h2>{Number(distance).toFixed(1)} km</h2><p>{duration} minutes · intensity {intensity}/5 · {load} cardio load. This will be included in your weekly training load and recovery.</p><button className="finish" onClick={logRun}>Save run</button></div></div>}</section>}

function SessionLogTimer({type,state,setState,label}){const [session,setSession]=useState(null),[tick,setTick]=useState(Date.now());useEffect(()=>{if(!session)return;const t=setInterval(()=>setTick(Date.now()),1000);return()=>clearInterval(t)},[session]);const elapsed=session?session.elapsed+(session.running?Date.now()-session.startedAt:0):0;const total=Math.floor(elapsed/1000),m=Math.floor(total/60),sec=total%60;const finish=()=>{if(!session)return;const duration=Math.max(0,Math.round(elapsed/1000));setState(s=>({...s,sessions:[...(s.sessions||[]),{date:today(),type,duration}]}));setSession(null)};return <section className="sessionTimer"><div><span className="eyebrow">{label}</span><strong>{String(m).padStart(2,'0')}:{String(sec).padStart(2,'0')}</strong><small>{session?.running?'SESSION RUNNING':session?'PAUSED':'START WHEN YOU BEGIN'}</small></div><div className="timerBtns">{!session?<button className="play" onClick={()=>setSession({startedAt:Date.now(),elapsed:0,running:true})}><Play/> Start</button>:session.running?<button className="play" onClick={()=>setSession(x=>({...x,elapsed:x.elapsed+(Date.now()-x.startedAt),running:false}))}><Pause/> Pause</button>:<button className="play" onClick={()=>setSession(x=>({...x,startedAt:Date.now(),running:true}))}><Play/> Resume</button>}{session&&<button onClick={finish}><Check/> Finish</button>}</div></section>}
function ReadinessCard({recovery,soreness,setSoreness}){return <section className={'readiness '+recovery.status.toLowerCase()}><div className="readinessMain"><div className="readinessIcon"><Battery/></div><div><span className="eyebrow">TRAINING READINESS</span><h3>{recovery.score}/100 · {recovery.status}</h3><p>{recovery.status==='READY'?'Basketball load is currently compatible with normal strength work.':recovery.status==='MODERATE'?'You have meaningful court fatigue. Lower-body work is automatically trimmed.':'Protect your jump quality today. Lower-body volume and loading are being reduced.'}</p></div></div><div className="loadStats"><div><b>{recovery.acute}</b><span>7-day BB load</span></div><div><b>{recovery.recentJumps}</b><span>jumps</span></div><div><b>{recovery.ratio}×</b><span>acute:chronic</span></div><label><span>Leg soreness</span><select value={soreness} onChange={e=>setSoreness(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option key={x} value={x}>{x}/5</option>)}</select></label></div></section>}
function Basketball({bb,setBb,state,setState,recovery}){const w=BASKETBALL[bb];const [duration,setDuration]=useState(50),[intensity,setIntensity]=useState(3),[jumps,setJumps]=useState(w.jumps),[showLog,setShowLog]=useState(false);const preview=calcBBLoad({duration,intensity,jumps,factor:w.factor});const logSession=()=>{setState(s=>({...s,bbLogs:[...(s.bbLogs||[]),{date:today(),type:bb,duration:Number(duration),intensity:Number(intensity),jumps:Number(jumps),factor:w.factor,load:preview}]}));setShowLog(false)};return <section><section className="hero simple"><div><div className="eyebrow">BASKETBALL OS</div><h1>{bb}</h1><p>{w.focus}</p></div><div className="heroStat"><span>{w.duration}</span><small>session</small></div></section><SessionLogTimer type="court" state={state} setState={setState} label="COURT SESSION"/><div className="bbTabs">{Object.keys(BASKETBALL).map(x=><button className={bb===x?'active':''} onClick={()=>{setBb(x);setJumps(BASKETBALL[x].jumps)}} key={x}>{x}</button>)}</div><div className="rules"><h2>Session structure</h2>{w.sessions.map((s,i)=><div className="bbRow" key={i}><span>0{i+1}</span><div><b>{s[0]}</b><small>{s[1]} {s[2]}</small></div><Check/></div>)}</div><div className="loadLogger"><div className="sectionHead"><div><span className="eyebrow">LOG SESSION</span><h2>How hard was it?</h2></div><div className="loadPreview"><b>{preview}</b><small>load</small></div></div><div className="loggerGrid"><label>Duration (min)<input type="number" min="5" value={duration} onChange={e=>setDuration(e.target.value)}/></label><label>Intensity (1–5)<select value={intensity} onChange={e=>setIntensity(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option key={x}>{x}</option>)}</select></label><label>Jumps / bounds<input type="number" min="0" value={jumps} onChange={e=>setJumps(e.target.value)}/></label></div><p className="loggerHint">The app weights jumping and hard court work more heavily because your dunk/jump goal depends on fresh lower legs.</p><button className="finish" onClick={()=>setShowLog(true)}>Log basketball session <span>{preview} load</span></button></div><div className="rules"><h2>Current recovery picture</h2><div className="miniMetrics"><div><b>{recovery.score}</b><span>readiness</span></div><div><b>{recovery.acute}</b><span>7-day load</span></div><div><b>{recovery.last48}</b><span>last 48h</span></div><div><b>{recovery.recentLeg}</b><span>lower-body lifts</span></div></div><p><b>Why this matters:</b> basketball is not treated as “extra cardio”. High-jump and high-intensity sessions can compete with leg strength and explosive recovery, so the gym programme responds to your recent load.</p></div><div className="rules"><h2>Basketball progression</h2><p><b>Quality first.</b> Increase makes, speed or difficulty only when technique stays clean.</p><p><b>Jump work.</b> Keep explosive reps low-fatigue. Stop a jump block when height or landing quality drops.</p><p><b>Weekly mix.</b> Pair 1–2 skill sessions with 1 athletic session and use recovery when legs are heavy.</p></div>{showLog&&<div className="modal" onClick={()=>setShowLog(false)}><div className="modalBox" onClick={e=>e.stopPropagation()}><span className="eyebrow">CONFIRM SESSION</span><h2>{preview} basketball load</h2><p>{duration} minutes · intensity {intensity}/5 · {jumps} jumps/bounds. This will feed the recovery engine and can change your next lower-body workout.</p><button className="finish" onClick={logSession}>Save session</button></div></div>}</section>}
function Programme({state,setState}){const sched=state.schedule||{};return <section><section className="hero simple"><div><div className="eyebrow">FIVE-DAY SPLIT</div><h1>Build, then progress.</h1><p>Strength, muscle and athleticism without burying recovery.</p></div></section><div className="mode"><div><b>Return mode</b><p>Weeks 1–3: keep 2–3 RIR, use the listed sets and rebuild consistency before chasing load.</p></div><button className={state.returnMode?'toggle on':'toggle'} onClick={()=>setState(s=>({...s,returnMode:!s.returnMode}))}><i/></button></div><div className="programGrid">{DAYS.map((d,i)=><div className="programCard" key={d}><span>DAY 0{i+1}</span><h3>{d}</h3><p>{PROGRAM[d].focus}</p><b>{PROGRAM[d].exercises.length} exercises · {PROGRAM[d].exercises.reduce((a,e)=>a+e[1],0)} sets</b></div>)}</div><div className="rules"><h2>Weekly schedule</h2><p>Choose a start day. Recovery-aware lower-body adjustments now also use your basketball load, jump count and leg soreness.</p><div className="scheduleGrid">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=><label key={d}>{d}<select value={sched[d]||'Rest'} onChange={e=>setState(s=>({...s,schedule:{...s.schedule,[d]:e.target.value}}))}>{['Rest',...DAYS].map(x=><option key={x}>{x}</option>)}</select></label>)}</div></div><div className="rules"><h2>Progression rules</h2><p><b>Double progression.</b> Stay in the rep range. Top of range across all sets + RIR ≥1 = increase load next time.</p><p><b>Stall detection.</b> Two consecutive sessions without improving reps/load = suggest 10% deload, then rebuild.</p><p><b>Warm-ups.</b> Compounds automatically get 2–3 ramp sets before work sets; isolation work gets 1 optional warm-up.</p><p><b>Basketball protection.</b> High recent court/jump load reduces lower-body sets and load rather than competing with your jump work.</p></div><div className="rules"><h2>Exercise library</h2><p>Add these as you progress or swap them into a session. Superset compatible exercises can be paired inside Train.</p><div className="programGrid">{Object.entries(EXTRA_EXERCISES).map(([group,items])=><div className="programCard" key={group}><span>{group.toUpperCase()}</span><p>{items.join(' · ')}</p></div>)}</div></div></section>}
function Progress({stats,history,recovery,bbLogs,state}){const recent=history.slice(-10).reverse();const max=Math.max(...stats.byDay.map(x=>x.count),1);return <section><div className="hero simple"><div><div className="eyebrow">TRAINING DATA</div><h1>Progress</h1><p>PRs, volume, consistency and basketball load in one place.</p></div></div><div className="statGrid"><div><Flame/><b>{stats.sessions}</b><span>gym sessions</span></div><div><Dumbbell/><b>{Math.round(stats.vol).toLocaleString()}</b><span>kg volume</span></div><div><Zap/><b>{stats.prs}</b><span>PRs</span></div></div><div className="rules"><h2>Session time</h2><div className="miniMetrics">{['train','court','run'].map(t=>{const mins=Math.round((state.sessions||[]).filter(x=>x.type===t).reduce((a,x)=>a+(x.duration||0),0)/60);return <div key={t}><b>{Math.floor(mins/60)}h {mins%60}m</b><span>{t==='train'?'TRAIN':t==='court'?'COURT':'RUN'}</span></div>})}</div></div><div className="rules"><h2>This week</h2><div className="miniMetrics"><div><b>{stats.weekGym}</b><span>gym sessions</span></div><div><b>{stats.weekBB.length}</b><span>basketball</span></div><div><b>{stats.weekRunKm.toFixed(1)}</b><span>run km</span></div><div><b>{(stats.weekBBLoad+stats.weekRunLoad).toFixed(0)}</b><span>court + run load</span></div></div><p>Water today: <b>{(stats.waterToday/1000).toFixed(2)} L</b> / {(Number(state.waterGoal||3000)/1000).toFixed(1)} L.</p></div><div className="rules"><h2>Basketball load</h2><div className="loadGauge"><div className="gaugeTrack"><i style={{width:`${recovery.score}%`}}/></div><div className="gaugeLabels"><b>{recovery.score}/100 readiness</b><span>{recovery.acute} 7-day load · {recovery.recentJumps} jumps · {recovery.ratio}× acute:chronic</span></div></div><div className="bbHistory">{bbLogs.slice(-6).reverse().map((x,i)=><div key={i}><b>{x.type}</b><span>{x.date} · {x.duration}m · {x.jumps} jumps</span><strong>{x.load}</strong></div>)}</div>{!bbLogs.length&&<p>Log basketball sessions to start building your load history.</p>}</div><div className="rules"><h2>Training frequency</h2>{stats.byDay.map(x=><div className="barRow" key={x.day}><span>{x.day}</span><div><i style={{width:`${(x.count/max)*100}%`}}/></div><b>{x.count}</b></div>)}</div><div className="sectionHead"><div><span className="eyebrow">RECENT</span><h2>History</h2></div></div><div className="history">{recent.length?recent.map((x,i)=><div className="historyRow" key={i}><div><b>{x.exercise} {x.pr?' · PR':''}</b><span>{x.day} · {x.date} · RIR {x.rir}</span></div><strong>{x.weight||'BW'} kg × {Math.max(...(x.reps||[0]))}</strong></div>):<div className="empty"><History/><h3>Your first session will show here.</h3><p>Complete a workout and your progression record will build automatically.</p></div>}</div></section>}
function SettingsPanel({state,setState}){const loads=state.loads||{};return <section><section className="hero simple"><div><div className="eyebrow">SETTINGS</div><h1>Starting loads</h1><p>Edit any starting weight. Your next-session suggestions will build from these numbers.</p></div></section><div className="rules"><h2>Editable starting weights</h2>{Object.entries(defaultLoad).map(([x,v])=><label className="loadSetting" key={x}><span>{x}</span><input type="number" step="0.5" value={loads[x]??v} onChange={e=>setState(s=>({...s,loads:{...s.loads,[x]:Number(e.target.value)}}))}/><b>kg</b></label>)}</div><div className="integration"><Watch/><div><b>Apple Health / Apple Watch</b><p>The web app can track training data now. Direct HealthKit workouts require a small native iPhone/Watch companion, which can later read this same workout history and write completed workouts to Health.</p></div></div></section>}
